"use client";

import { useCallback, useEffect, useState } from "react";
import type { QualityApiState, QualityCase, EvalRun, RunItem, ReviewDecision, CandidateVersion, SkillInfo, EventContext } from "@/lib/quality/types";
import { Activity, AlertCircle, AlertTriangle, ArrowDownUp, ArrowRight, Bell, Check, ChevronDown, CircleHelp, Clock3, Download, FileJson2, FlaskConical, Gauge, Layers3, LoaderCircle, MessageSquareText, Microscope, PanelRightClose, Plus, RefreshCw, Search, ShieldCheck, SlidersHorizontal, Sparkles, Target, Upload, Wrench, X, Zap } from "lucide-react";

type Section = "overview" | "runs" | "compare" | "reviews" | "tools";
type FeedbackRow = { id: string; caseId: string; kind: string; note: string; status?: "pending_review" | "confirmed" | "dismissed" | "needs_evidence" | "resolved"; decision?: string; createdAt: string; resolvedAt?: string; resolutionNote?: string };
type RegressionRow = { id: string; runId: string; caseId: string; addedAt: string; candidateVersionId?: string; evaluationVersionId?: string; caseSnapshot?: Omit<QualityCase, "answers">; answerText?: string; findings?: RunItem["findings"] };
type UiState = Omit<QualityApiState, "feedback"> & { feedback: FeedbackRow[]; skills?: SkillInfo[]; regressionCases?: RegressionRow[] };
const intentNames: Record<string, string> = { fact_query: "事实查询", knowledge: "知识解释", market_event: "行情解读", comparison: "产品比较", suitability: "适配咨询" };
const statusNames: Record<string, string> = { pass: "通过", fail: "不通过", pending_verification: "待核验", needs_review: "需复核", idle: "未评测" };
const severityNames: Record<string, string> = { critical: "严重", high: "高", medium: "中", low: "低" };
const decisionNames: Record<string, string> = { confirmed: "确认问题", false_positive: "判为误报", needs_evidence: "补充证据" };
const example = { dataset: { cases: [{ caseId: "import-demo-001", question: "示例：虚构公司甲最近一期营业收入是多少？", intent: "fact_query", askedAt: "2026-11-09T09:00:00+08:00", kyc: { profileId: "anon-import-demo", experience: "beginner", riskTolerance: "medium", horizonMonths: 12, liquidityNeed: "low", purpose: "学习" }, synthetic: true, expectedChecks: ["来源与统计期间明确"], evidence: [], answers: { "candidate-a": { text: "请填写候选 A 回答。", generatedAt: "2026-11-09T09:01:00+08:00", provenance: "preset" } } }] } };

export default function QualityConsole() {
  const [state, setState] = useState<UiState | null>(null);
  const [section, setSection] = useState<Section>("overview");
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState("");
  const [toast, setToast] = useState<{ text: string; error?: boolean } | null>(null);
  const [selected, setSelected] = useState<{ run: EvalRun; item: RunItem; c: Omit<QualityCase, "answers"> } | null>(null);
  const [versionId, setVersionId] = useState("");
  const [query, setQuery] = useState("");
  const [intentFilter, setIntentFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [compareA, setCompareA] = useState("");
  const [compareB, setCompareB] = useState("");
  const [compareRunA, setCompareRunA] = useState("");
  const [compareRunB, setCompareRunB] = useState("");
  const [modal, setModal] = useState<"import" | "feedback" | null>(null);
  const [importText, setImportText] = useState("");
  const [feedbackCase, setFeedbackCase] = useState("");
  const [feedbackKind, setFeedbackKind] = useState("事实可能错误");
  const [feedbackNote, setFeedbackNote] = useState("");
  const [reviewNote, setReviewNote] = useState("");
  const [feedbackResolutionId, setFeedbackResolutionId] = useState("");
  const [feedbackResolutionNote, setFeedbackResolutionNote] = useState("");
  const [selectedRunId, setSelectedRunId] = useState("");
  const [selectedCaseIds, setSelectedCaseIds] = useState<string[]>([]);
  const [ifindInfo, setIfindInfo] = useState<{ configured?: boolean; source?: string; supported?: { symbol: string; date: string; field: string }[] } | null>(null);
  const [ifindResult, setIfindResult] = useState<{ status: string; query?: unknown; retrievedAt?: string; source?: string; content?: { type: string; text: string }[]; notice?: string; verification?: { status: "MATCH" | "MISMATCH" | "UNVERIFIED"; claimedValue: number; referenceValue: number | null; unit: string; symbol: string; date: string; adjustment: string; evidenceId: string; reason: string } } | null>(null);
  const [ifindClaim, setIfindClaim] = useState("");
  const [judgeInfo, setJudgeInfo] = useState<{ configured?: boolean; model?: string; notice?: string } | null>(null);
  const [judgeResult, setJudgeResult] = useState<{ status: string; model?: string; skillVersion?: string; createdAt?: string; result?: { overallStatus: string; summary: string; findings: { dimension: string; severity: string; quote: string; reason: string; evidenceIds: string[]; requiresReview: true }[] }; notice?: string } | null>(null);

  const notify = (text: string, error = false) => { setToast({ text, error }); window.setTimeout(() => setToast(null), 3800); };
  const refresh = useCallback(async (quiet = false) => {
    if (!quiet) setLoading(true);
    try {
      const response = await fetch("/api/quality", { cache: "no-store" });
      if (!response.ok) throw new Error(`读取评测台失败（${response.status}）`);
      const data = await response.json() as UiState;
      setState(data);
      setSelectedRunId((current) => current && data.runs.some((r) => r.id === current) ? current : data.runs[0]?.id ?? "");
      setVersionId((current) => current && data.versions.some((v) => v.id === current) ? current : data.versions[0]?.id ?? "");
      setCompareA((current) => current && data.versions.some((v) => v.id === current) ? current : data.versions[0]?.id ?? "");
      setCompareB((current) => current && data.versions.some((v) => v.id === current) ? current : data.versions[1]?.id ?? data.versions[0]?.id ?? "");
      setCompareRunA((current) => current && data.runs.some((r) => r.id === current) ? current : data.runs.find((r) => r.candidateVersionId === (data.versions[0]?.id ?? ""))?.id ?? "");
      setCompareRunB((current) => current && data.runs.some((r) => r.id === current) ? current : data.runs.find((r) => r.candidateVersionId === (data.versions[1]?.id ?? ""))?.id ?? "");
    } catch (err) { notify(err instanceof Error ? err.message : "暂时无法读取评测数据", true); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { void refresh(); }, [refresh]);
  useEffect(() => { let active = true; fetch("/api/tools/ifind", { cache: "no-store" }).then(async (r) => { if (!r.ok) throw new Error(); return await r.json() as { configured?: boolean; source?: string; supported?: { symbol: string; date: string; field: string }[] }; }).then((d) => { if (active) setIfindInfo(d); }).catch(() => { if (active) setIfindInfo({ configured: false }); }); fetch("/api/tools/judge", { cache: "no-store" }).then(async (r) => { if (!r.ok) throw new Error(); return await r.json() as { configured?: boolean; model?: string; notice?: string }; }).then((d) => { if (active) setJudgeInfo(d); }).catch(() => { if (active) setJudgeInfo({ configured: false }); }); return () => { active = false; }; }, []);

  async function act(action: string, payload: Record<string, unknown> = {}, opts: { quiet?: boolean; success?: string } = {}) {
    setBusy(action);
    try {
      const response = await fetch("/api/quality", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action, ...payload }) });
      const body = await response.json().catch(() => ({})) as { error?: string; message?: string } & Partial<UiState>;
      if (!response.ok) throw new Error(body.error || body.message || `操作失败（${response.status}）`);
      setState(body as UiState);
      if (action === "reset") {
        setSelectedRunId(""); setSelectedCaseIds([]); setCompareRunA(""); setCompareRunB("");
        setVersionId(body.versions?.[0]?.id ?? ""); setCompareA(body.versions?.[0]?.id ?? ""); setCompareB(body.versions?.[1]?.id ?? body.versions?.[0]?.id ?? "");
      }
      if (opts.success) notify(opts.success);
      return body as UiState;
    } catch (err) { notify(err instanceof Error ? err.message : "操作失败，请稍后重试", true); return null; }
    finally { setBusy(""); }
  }

  if (loading && !state) return <div className="loading"><LoaderCircle className="spin" size={17} style={{ marginRight: 8 }} />正在加载质检台…</div>;
  const safeState = state ?? { cases: [], versions: [], evaluationVersions: [], runs: [], reviews: [], feedback: [], regressionCases: [], tools: [], skills: [] } as UiState;
  const versions = safeState.versions ?? [];
  const cases = safeState.cases ?? [];
  const runs = safeState.runs ?? [];
  const latestRun = runs[0];
  const taskRun = runs.find((r) => r.id === selectedRunId) ?? latestRun;
  const taskItems = new Map<string, { run: EvalRun; item: RunItem }>((taskRun?.items ?? []).map((item) => [item.caseId, { run: taskRun!, item }]));
  const activeVersion = versions.find((v) => v.id === versionId) ?? versions[0];
  const latestItems = new Map<string, { run: EvalRun; item: RunItem }>();
  for (const r of runs) for (const item of r.items) if (!latestItems.has(item.caseId)) latestItems.set(item.caseId, { run: r, item });
  const taskCaseRecords = taskRun?.caseSnapshots?.length ? taskRun.caseSnapshots.map((snapshot) => ({ ...snapshot, answers: cases.find((c) => c.caseId === snapshot.caseId)?.answers ?? {} } as QualityCase)) : cases;
  const reviewQueue = cases.map((c) => ({ c, result: latestItems.get(c.caseId) })).filter(({ result }) => result && result.item.reviewStatus === "pending" && result.item.findings.some((f) => f.reviewRequired));
  const pendingFeedback = safeState.feedback.filter((f) => !f.status || f.status === "pending_review");
  const reviewCount = reviewQueue.length + pendingFeedback.length;
  const shownCases = taskCaseRecords.filter((c) => {
    const it = taskItems.get(c.caseId)?.item;
    return (intentFilter === "all" || c.intent === intentFilter) && (statusFilter === "all" || (it?.overallStatus ?? "idle") === statusFilter) && (!query || `${c.question} ${c.caseId}`.toLowerCase().includes(query.toLowerCase()));
  });
  const selectedRun = (compareId: string) => runs.find((r) => r.candidateVersionId === compareId);
  const runA = runs.find((r) => r.id === compareRunA && r.candidateVersionId === compareA) ?? selectedRun(compareA), runB = runs.find((r) => r.id === compareRunB && r.candidateVersionId === compareB) ?? selectedRun(compareB);
  const itemMap = (r?: EvalRun) => new Map<string, RunItem>((r?.items ?? []).map((i) => [i.caseId, i]));
  const mapA = itemMap(runA), mapB = itemMap(runB);
  const commonIds = [...mapA.keys()].filter((id) => mapB.has(id));
  const missingInA = cases.filter((c) => !mapA.has(c.caseId)).length;
  const missingInB = cases.filter((c) => !mapB.has(c.caseId)).length;
  const diffClass = (id: string) => { const a = mapA.get(id)?.overallStatus, b = mapB.get(id)?.overallStatus; if (!a || !b) return ""; const badA = a === "fail" || a === "needs_review", badB = b === "fail" || b === "needs_review"; return badA && b === "pass" ? "fixed" : a === "pass" && badB ? "new" : badA && badB ? "ongoing" : ""; };
  const diffCounts = { fixed: commonIds.filter((id) => diffClass(id) === "fixed").length, ongoing: commonIds.filter((id) => diffClass(id) === "ongoing").length, added: commonIds.filter((id) => diffClass(id) === "new").length };
  const intentSummary = Object.keys(intentNames).map((id) => ({ id, name: intentNames[id], count: cases.filter((c) => c.intent === id).length, fails: cases.filter((c) => c.intent === id && ["fail", "needs_review"].includes(latestItems.get(c.caseId)?.item.overallStatus ?? "")).length }));
  const passN = latestRun?.items.filter((i) => i.overallStatus === "pass").length ?? 0;
  const failN = latestRun?.items.filter((i) => i.overallStatus === "fail" || i.overallStatus === "needs_review").length ?? 0;
  const pendingN = latestRun?.items.filter((i) => i.overallStatus === "pending_verification").length ?? 0;
  const factMatched = latestRun?.items.reduce((n, i) => n + i.factNumerator, 0) ?? 0;
  const factChecked = latestRun?.items.reduce((n, i) => n + i.factDenominator, 0) ?? 0;
  const verified = latestRun?.items.reduce((n, i) => n + i.verifiedNumerator, 0) ?? 0;
  const verifiable = latestRun?.items.reduce((n, i) => n + i.verifiedDenominator, 0) ?? 0;
  const getCase = (id: string) => cases.find((c) => c.caseId === id);
  const selectedStoredAnswer = selected ? getCase(selected.c.caseId)?.answers[selected.run.candidateVersionId] : undefined;
  const selectedAnswerGeneratedAt = selected && selectedStoredAnswer && selectedStoredAnswer.text === selected.item.answerText ? selectedStoredAnswer.generatedAt : undefined;
  const openCase = (c: QualityCase | Omit<QualityCase, "answers">, res?: { run: EvalRun; item: RunItem }) => {
    if (res) {
      const snapshot = res.run.caseSnapshots?.find((entry) => entry.caseId === c.caseId);
      const current = getCase(c.caseId);
      setSelected({ c: snapshot ?? c as Omit<QualityCase, "answers">, run: res.run, item: res.item });
      setFeedbackCase(current?.caseId ?? c.caseId);
    } else { setSelected(null); setFeedbackCase(c.caseId); }
    setReviewNote(""); setJudgeResult(null);
  };

  async function evaluateVersion(id: string, success = "规则评测已完成，结果已刷新。", requestedIds?: string[]) {
    const available = cases.filter((c) => c.answers[id]?.text?.trim()).map((c) => c.caseId);
    const caseIds = (requestedIds ?? available.slice(0, 20)).filter((caseId) => available.includes(caseId));
    if (!caseIds.length) { notify("此版本没有已保存回答，无法运行评测。", true); return; }
    if (caseIds.length > 20) { notify("单次最多可评测 20 条，请减少所选案例。", true); return; }
    const result = await act("evaluate", { versionId: id, caseIds }, { success });
    if (result?.runs?.[0]) { setSelectedRunId(result.runs[0].id); setSection("runs"); }
  }
  async function evaluate() {
    if (!activeVersion) { notify("当前没有候选回答版本", true); return; }
    await evaluateVersion(activeVersion.id);
  }
  async function evaluateSelectedCases() {
    if (!activeVersion) { notify("当前没有候选回答版本", true); return; }
    if (!selectedCaseIds.length) { notify("请先勾选要运行的案例", true); return; }
    await evaluateVersion(activeVersion.id, `已完成 ${selectedCaseIds.length} 条案例的规则评测。`, selectedCaseIds);
    setSelectedCaseIds([]);
  }
  async function submitReview(decision: ReviewDecision) {
    if (!selected || !reviewNote.trim()) { notify("请填写复核理由后再提交", true); return; }
    const result = await act("review", { runId: selected.run.id, caseId: selected.c.caseId, decision, note: reviewNote.trim() }, { success: "复核记录已保存。" });
    if (result) { setSelected(null); setReviewNote(""); }
  }
  async function submitFeedback() {
    if (!feedbackCase || !feedbackNote.trim()) { notify("请选择案例并填写反馈内容", true); return; }
    const result = await act("feedback", { caseId: feedbackCase, kind: feedbackKind, note: feedbackNote.trim() }, { success: "反馈已加入人工检查队列。" });
    if (result) { setModal(null); setFeedbackNote(""); }
  }
  async function resolveFeedback(feedbackId: string, decision: "confirmed" | "dismissed" | "needs_evidence") {
    if (!feedbackResolutionNote.trim()) { notify("请填写处理说明后再保存", true); return; }
    const result = await act("resolve_feedback", { feedbackId, decision, note: feedbackResolutionNote.trim() }, { success: "用户反馈已处理并留档。" });
    if (result) { setFeedbackResolutionId(""); setFeedbackResolutionNote(""); }
  }
  async function addRegression(runId: string, caseId: string) {
    await act("add_regression", { runId, caseId }, { success: "已加入回归案例集。" });
  }
  function downloadRegression() {
    setBusy("export");
    void fetch("/api/quality", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "export" }) }).then(async (response) => {
      const data = await response.json() as { error?: string; schemaVersion?: string; exportedAt?: string; regressionCases?: RegressionRow[] }; if (!response.ok) throw new Error(data.error || "回归集导出失败");
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = "已确认问题回归集.json"; a.click(); URL.revokeObjectURL(url); notify("回归集 JSON 已导出。");
    }).catch((err) => notify(err instanceof Error ? err.message : "回归集导出失败", true)).finally(() => setBusy(""));
  }
  async function resetDemo() {
    const confirmed = window.confirm("重置当前会话演示数据？这会清空本会话的评测运行、复核、反馈和回归记录，并恢复 20 条预置测试案例。其他会话不受影响。");
    if (confirmed) await act("reset", {}, { success: "当前会话已重置，已恢复 20 条预置案例。" });
  }
  async function importData() {
    try { const dataset = JSON.parse(importText); const result = await act("import", { dataset }, { success: "问答集已导入。" }); if (result) { setModal(null); setImportText(""); } }
    catch (err) { if (!(err instanceof SyntaxError)) notify("导入失败", true); else notify("JSON 格式有误，请检查后重试。", true); }
  }
  async function probe(toolId: string) { await act("probe", { toolId, scenario: "timeout" }, { success: "探测完成，状态已刷新。" }); }
  async function generate(c: Pick<QualityCase, "caseId">, version?: string) {
    const res = await act("generate", { caseId: c.caseId, versionId: version });
    if (res) {
      const generated = res.versions.find((v) => !versions.some((known) => known.id === v.id));
      if (generated) setVersionId(generated.id);
      notify(generated ? `候选回答已生成并切换至「${generated.name}」。评测仅会纳入已有回答的案例。` : "候选回答已生成。", false);
    }
  }
  async function ifindQuery() {
    setBusy("ifind");
    try { const r = await fetch("/api/tools/ifind", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ symbol: "300033.SZ", date: "2026-11-06", field: "close", ...(ifindClaim.trim() ? { claimValue: Number(ifindClaim), claimUnit: "元" } : {}) }) }); const d = await r.json() as NonNullable<typeof ifindResult>; setIfindResult(d); if (!r.ok) notify(d.notice || "iFinD查询失败", true); else notify(d.notice || "iFinD查询返回完成"); }
    catch (err) { notify(err instanceof Error ? err.message : "iFinD服务暂不可用", true); }
    finally { setBusy(""); }
  }
  async function judgeCase(c: Pick<QualityCase, "caseId">, version?: string) {
    setBusy("judge");
    try { const r = await fetch("/api/tools/judge", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ caseId: c.caseId, versionId: version }) }); const d = await r.json() as NonNullable<typeof judgeResult>; setJudgeResult(d); if (!r.ok) notify(d.notice || "AI辅助评测暂不可用", true); else notify(d.notice || "AI辅助建议已返回"); }
    catch (err) { notify(err instanceof Error ? err.message : "AI辅助评测暂不可用", true); }
    finally { setBusy(""); }
  }
  function exportRun(run: EvalRun) { const blob = new Blob([JSON.stringify(run, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = `quality-run-${run.id}.json`; a.click(); URL.revokeObjectURL(url); }
  function downloadExample() { const blob = new Blob([JSON.stringify(example, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = "投资问答集导入示例.json"; a.click(); URL.revokeObjectURL(url); }
  function downloadIfind() { if (!ifindResult) return; const blob = new Blob([JSON.stringify({ query: ifindResult.query, retrievedAt: ifindResult.retrievedAt, source: ifindResult.source, content: ifindResult.content, verification: ifindResult.verification, notice: ifindResult.notice }, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = `ifind-${ifindResult.verification?.evidenceId || "query"}.json`; a.click(); URL.revokeObjectURL(url); }

  return <div className="shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark"><Activity size={19} strokeWidth={2.2} /></div><div><strong>投研回答质检台</strong><small>RESEARCH QA WORKSPACE</small></div></div>
      <div className="nav-label">工作空间</div>
      <nav className="nav-list">
        {([ ["overview", Gauge, "概览"], ["runs", Layers3, "评测任务"], ["compare", ArrowDownUp, "版本比较"], ["reviews", ShieldCheck, "人工复核"], ["tools", Wrench, "工具与 Skills"] ] as const).map(([id, Icon, label]) => <button key={id} aria-label={label} className={`nav-item ${section === id ? "active" : ""}`} onClick={() => setSection(id)}><Icon size={16} /><span>{label}</span>{id === "reviews" && reviewCount > 0 && <i className="count">{reviewCount}</i>}</button>)}
      </nav>
      <div className="side-bottom"><div className="env"><div className="env-head"><i className="dot" />演示环境 <span style={{ marginLeft: "auto", color: "#81999a" }}>v0.8</span></div><p>数据集与行情快照均为合成演示数据</p></div><div className="user"><div className="avatar">研</div><div><b>研究质量团队</b><span>评测工作区</span></div></div></div>
    </aside>
    <main className="main"><div className="topbar"><div className="crumb"><span>工作空间</span><span>/</span><b>{({ overview: "概览", runs: "评测任务", compare: "版本比较", reviews: "人工复核", tools: "工具与 Skills" })[section]}</b></div><div className="top-actions"><div className="top-chip"><span className="dot" />规则评测已就绪</div><button aria-label="刷新数据" className="top-icon" title="刷新数据" onClick={() => void refresh(true)}><RefreshCw size={14} /></button><button aria-label="提交反馈" className="top-icon" title="反馈" onClick={() => { setFeedbackCase(cases[0]?.caseId ?? ""); setModal("feedback"); }}><Bell size={14} /></button></div></div>
      <div className="content"><div className="page-head"><div><div className="eyebrow"><span className="dot" />质量治理 · 工作台</div><h1>{({ overview: "投研回答质量，一屏掌握", runs: "评测任务", compare: "版本效果对照", reviews: "人工复核队列", tools: "工具与 Skills" })[section]}</h1><p>{section === "overview" ? "从规则评测、证据核验到人工复核，持续把每条投资回答变成可追溯的质量记录。" : section === "compare" ? "在相同案例上对照候选回答，查看问题修复、持续与新增情况。" : section === "tools" ? "查看外部数据连接、运行探测，并了解当前生效的评测规则。" : "查看每条问答的评测结果、证据依据与复核状态。"}</p></div><div className="actions"><button className="btn" onClick={() => setModal("import")}><Upload />导入问答集</button>{latestRun && <button className="btn" onClick={() => exportRun(latestRun)}><Download />导出结果</button>}<button disabled={!!busy} className="btn primary" onClick={() => void evaluate()}>{busy === "evaluate" ? <LoaderCircle className="spin" /> : <FlaskConical />}开始规则评测</button></div></div>
        <div className="notice"><CircleHelp size={15} /><span><strong>数据边界：</strong>当前问答案例和证据来自合成快照，仅用于演示规则与复核流程；不代表实时行情或投资建议。</span><span className="tail">评测采用确定性规则，模型生成需单独配置</span></div>
        {section === "overview" && <>
          <div className="stats">
            <Stat Icon={Layers3} title="测试案例" value={cases.length} note={`${safeState.regressionCases?.length ?? 0} 条已确认回归样例`} />
            <Stat Icon={Activity} title="最近评测" value={latestRun ? `${latestRun.items.length} 条` : "—"} note={latestRun ? new Date(latestRun.createdAt).toLocaleString("zh-CN", { hour12: false }) : "尚未运行评测"} />
            <Stat Icon={AlertTriangle} title="问题与待核验" value={latestRun ? failN + pendingN : "—"} note={latestRun ? `不通过/需复核 ${failN} · 待核验 ${pendingN}` : "运行评测后显示"} />
            <Stat Icon={ShieldCheck} title="待人工复核" value={reviewCount} note={`复核案例 ${reviewQueue.length} · 用户反馈 ${pendingFeedback.length}`} accent />
          </div>
            <div className="grid-main"><div className="card"><div className="card-head"><div><div className="card-title">最近一次规则评测</div><div className="card-sub">{latestRun ? `${versions.find((v) => v.id === latestRun.candidateVersionId)?.name ?? latestRun.candidateVersionId} · ${new Date(latestRun.createdAt).toLocaleString("zh-CN", { hour12: false })}` : "完成一次评测后，这里会汇总真实规则执行结果"}</div></div>{latestRun && <button className="btn small" onClick={() => { setSection("runs"); }}>查看任务 <ArrowRight size={12} /></button>}</div><div className="card-body">{latestRun ? <><div className="run-row"><div className="run-emblem"><Microscope /></div><div className="run-copy"><b>确定性规则运行完成</b><span>{latestRun.items.length} 条案例 · 规则集 {safeState.evaluationVersions?.find((v) => v.id === latestRun.evaluationVersionId)?.name ?? "当前版本"}</span></div><div className="run-number"><b>{latestRun.items.length}</b><span>已评测案例</span></div></div><div className="mini-bar"><span className="bar-pass" style={{ width: `${100 * passN / Math.max(1, latestRun.items.length)}%` }} /><span className="bar-fail" style={{ width: `${100 * failN / Math.max(1, latestRun.items.length)}%` }} /><span className="bar-pending" style={{ width: `${100 * pendingN / Math.max(1, latestRun.items.length)}%` }} /></div><div className="run-legend"><span><i className="legend-dot" style={{ background: "#47ae8f" }} />通过 {passN}/{latestRun.items.length}</span><span><i className="legend-dot" style={{ background: "#d86b5f" }} />不通过/复核 {failN}/{latestRun.items.length}</span><span><i className="legend-dot" style={{ background: "#dba74e" }} />待核验 {pendingN}/{latestRun.items.length}</span></div><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 9, marginTop: 16 }}><Ratio label="已核验事实准确率" numerator={factMatched} denominator={factChecked} /><Ratio label="证据核验覆盖率" numerator={verified} denominator={verifiable} /></div><div className="section-label">按问答意图分布</div><div className="progress-list">{intentSummary.map((x) => <div className="progress-line" key={x.id}><span>{x.name}</span><div className="progress-track"><i style={{ width: `${100 * x.count / Math.max(1, cases.length)}%` }} /></div><strong>{x.count} 条</strong></div>)}</div></> : <div className="empty"><strong>还没有评测运行</strong>已准备好 {cases.length} 条合成测试案例，选择候选版本后即可运行确定性规则。<div style={{ marginTop: 14 }}><button className="btn primary" onClick={() => void evaluate()}><FlaskConical size={13} />运行首次评测</button></div></div>}</div></div>
            <div className="right-stack"><div className="card review-card"><div className="card-head"><div><div className="card-title">待处理队列</div><div className="card-sub">需复核案例与用户反馈</div></div><div className="review-total">{reviewCount}</div></div><div className="card-body">{reviewQueue.slice(0, 3).map(({ c, result }) => <div className="queue-item" key={c.caseId} onClick={() => { if (result) openCase(c, result); setSection("reviews"); }}><i className="queue-bullet" /><div className="queue-copy"><b>{c.question}</b><span>{c.caseId} · {intentNames[c.intent]}</span></div><ArrowRight className="queue-arrow" /></div>)}{pendingFeedback.slice(0, 2).map((f) => <div className="queue-item" key={f.id}><i className="queue-bullet" /><div className="queue-copy"><b>{f.kind} · {getCase(f.caseId)?.question ?? f.caseId}</b><span>用户反馈 · {f.note}</span></div></div>)}{reviewCount === 0 && <div className="empty" style={{ padding: "18px 5px" }}>当前没有待处理项目</div>}<button className="btn small" style={{ width: "100%", marginTop: 8 }} onClick={() => setSection("reviews")}>打开复核队列 <ArrowRight size={12} /></button></div></div>
              <div className="card"><div className="card-head"><div><div className="card-title">当前候选版本</div><div className="card-sub">选择要运行评测的回答版本</div></div><SlidersHorizontal size={15} color="#93a0a1" /></div><div className="card-body">{activeVersion ? <><div className="version-head"><div className="version-mark">{activeVersion.name.slice(-1)}</div><div><b>{activeVersion.name}</b><small>{activeVersion.model} · {activeVersion.promptVersion}</small></div></div><p style={{ color: "#7d8b8c", fontSize: 10, lineHeight: 1.6, margin: "10px 0" }}>{activeVersion.description}</p><select className="filter" style={{ width: "100%" }} value={versionId} onChange={(e) => setVersionId(e.target.value)}>{versions.map((v) => <option key={v.id} value={v.id}>{v.name} · {v.promptVersion}</option>)}</select><div style={{ fontSize: 9, color: "#93a0a1", marginTop: 8 }}>数据快照：{activeVersion.dataSnapshot}</div></> : <div className="empty">暂无候选版本</div>}</div></div></div></div>
          <div className="card" style={{ marginTop: 14 }}><div className="card-head"><div><div className="card-title">案例速览</div><div className="card-sub">{latestRun ? "点击案例行查看问答详情、证据和人工复核操作" : "预置问答均为合成样例；先运行评测以查看结果"}</div></div><button className="btn small" onClick={() => setSection("runs")}>全部案例 <ArrowRight size={12} /></button></div><div className="table-wrap"><CaseTable cases={cases.slice(0, 5)} items={latestItems} onOpen={(c) => { const r = latestItems.get(c.caseId); openCase(c, r); }} /></div></div>
        </>}
        {section === "runs" && <div className="card"><div className="card-head"><div><div className="card-title">案例评测结果</div><div className="card-sub">{taskRun ? `${versions.find((v) => v.id === taskRun.candidateVersionId)?.name ?? taskRun.candidateVersionId} · ${new Date(taskRun.createdAt).toLocaleString("zh-CN", { hour12: false })} · ${taskRun.items.length} 条` : `预置数据集 · ${cases.length} 条合成案例`}</div></div><div style={{ display: "flex", gap: 7 }}><button className="btn small" onClick={() => setModal("import")}><Plus size={12} />导入数据</button><button className="btn small" onClick={() => taskRun && exportRun(taskRun)} disabled={!taskRun}><Download size={12} />导出 JSON</button></div></div><div className="card-body"><div className="tabs"><button className="tab active">案例结果 <i className="pill">{shownCases.length}</i></button><button className="tab" onClick={() => setSection("reviews")}>待人工复核 <i className="pill">{reviewCount}</i></button></div><div className="filters"><select className="filter" value={selectedRunId} onChange={(e) => setSelectedRunId(e.target.value)} aria-label="选择历史运行"><option value="">尚无历史运行</option>{runs.map((r) => <option value={r.id} key={r.id}>{versions.find((v) => v.id === r.candidateVersionId)?.name ?? r.candidateVersionId} · {new Date(r.createdAt).toLocaleString("zh-CN", { hour12: false })} · {r.items.length} 条</option>)}</select><select className="filter" value={versionId} onChange={(e) => { setVersionId(e.target.value); setSelectedCaseIds([]); }} aria-label="候选回答版本">{versions.map((v) => <option key={v.id} value={v.id}>{v.name}</option>)}</select><button className="btn small" onClick={() => void evaluate()} disabled={!!busy}><FlaskConical size={12} />运行此版本</button><div className="search-wrap"><Search /><input className="search" placeholder="搜索问题或案例 ID" value={query} onChange={(e) => setQuery(e.target.value)} /></div><select className="filter" value={intentFilter} onChange={(e) => setIntentFilter(e.target.value)}><option value="all">全部意图</option>{Object.entries(intentNames).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select><select className="filter" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}><option value="all">全部状态</option>{Object.entries(statusNames).filter(([id]) => id !== "idle").map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select><button className="btn small primary" onClick={() => void evaluateSelectedCases()} disabled={!selectedCaseIds.length || !!busy}><FlaskConical size={12} />运行所选 {selectedCaseIds.length}/20</button><button className="btn small" onClick={() => setSelectedCaseIds(shownCases.slice(0, 20).filter((c) => c.answers[versionId]?.text?.trim()).map((c) => c.caseId))}>选择当前筛选</button><button className="btn small" onClick={() => setSelectedCaseIds([])} disabled={!selectedCaseIds.length}>清除选择</button><span style={{ marginLeft: "auto", color: "#9aa5a5", fontSize: 9 }}>结果数 {shownCases.length}/{cases.length}</span></div><CaseTable cases={shownCases} items={taskItems} selectable checkedIds={selectedCaseIds} answerVersionId={versionId} onToggle={(id) => setSelectedCaseIds((current) => current.includes(id) ? current.filter((v) => v !== id) : current.length >= 20 ? (notify("单次最多勾选 20 条案例", true), current) : [...current, id])} onOpen={(c) => { const r = taskItems.get(c.caseId); openCase(c, r); }} /></div></div>}
        {section === "compare" && <><div className="card"><div className="card-head"><div><div className="card-title">候选回答版本</div><div className="card-sub">比较需要基于实际规则评测结果；尚未运行的版本不会显示虚构指标</div></div><ArrowDownUp size={16} color="#839292" /></div><div className="card-body"><div className="version-grid">{versions.map((v, i) => <VersionCard key={v.id} version={v} letter={i ? "B" : "A"} />)}</div><div className="compare-controls" style={{ marginTop: 15 }}><label style={{ fontSize: 10, color: "#778587" }}>对照</label><select value={compareA} onChange={(e) => setCompareA(e.target.value)}>{versions.map((v) => <option key={v.id} value={v.id}>{v.name}</option>)}</select><select aria-label="选择A版本运行记录" value={compareRunA} onChange={(e) => setCompareRunA(e.target.value)}><option value="">最新可用运行</option>{runs.filter((r) => r.candidateVersionId === compareA).map((r) => <option key={r.id} value={r.id}>{new Date(r.createdAt).toLocaleString("zh-CN", { hour12: false })} · {r.items.length}条</option>)}</select><span style={{ color: "#a0aaaa", fontSize: 10 }}>与</span><select value={compareB} onChange={(e) => setCompareB(e.target.value)}>{versions.map((v) => <option key={v.id} value={v.id}>{v.name}</option>)}</select><select aria-label="选择B版本运行记录" value={compareRunB} onChange={(e) => setCompareRunB(e.target.value)}><option value="">最新可用运行</option>{runs.filter((r) => r.candidateVersionId === compareB).map((r) => <option key={r.id} value={r.id}>{new Date(r.createdAt).toLocaleString("zh-CN", { hour12: false })} · {r.items.length}条</option>)}</select><button className="btn small" onClick={() => { setVersionId(compareA); void evaluateVersion(compareA, "版本 A 评测完成"); }}><FlaskConical size={12} />运行 A</button><button className="btn small primary" onClick={() => { setVersionId(compareB); void evaluateVersion(compareB, "版本 B 评测完成"); }}><FlaskConical size={12} />运行 B</button></div><div className="diff-grid"><DiffStat label="已修复" value={runA && runB ? diffCounts.fixed : "—"} detail="A 有问题，B 已改善" color="#3d916f" /><DiffStat label="持续存在" value={runA && runB ? diffCounts.ongoing : "—"} detail="两版均有问题" color="#b27e36" /><DiffStat label="B 新增问题" value={runA && runB ? diffCounts.added : "—"} detail="A 通过，B 出现问题" color="#bb6157" /><DiffStat label="共同评测案例" value={runA && runB ? `${commonIds.length}/${Math.max(runA.items.length, runB.items.length)}` : "—"} detail={runA && runB ? `A 缺 ${missingInA} 条 · B 缺 ${missingInB} 条` : "两版共同评测案例"} color="#536d70" /></div></div></div><div className="card" style={{ marginTop: 13 }}><div className="card-head"><div><div className="card-title">逐案例差异</div><div className="card-sub">结果状态分类来自对应版本的已保存运行；表格只配对共同案例，未覆盖数量单独显示</div></div></div><div className="card-body">{!runA || !runB ? <div className="empty"><strong>版本结果尚未齐备</strong>请分别运行两个候选版本的规则评测后再比较。</div> : <div className="table-wrap"><table className="case-table"><thead><tr><th>测试案例</th><th>{versions.find((v) => v.id === compareA)?.name} 状态</th><th>{versions.find((v) => v.id === compareB)?.name} 状态</th><th>差异归类</th><th></th></tr></thead><tbody>{commonIds.map((id) => { const c = getCase(id)!; const a = mapA.get(id)!; const b = mapB.get(id)!; const kind = diffClass(id); return <tr key={id} onClick={() => openCase(c, { run: runB, item: b })}><td><div className="case-id">{id} · {intentNames[c.intent]}</div><span className="case-question">{c.question}</span></td><td onClick={(e) => e.stopPropagation()}><button aria-label={`查看${versions.find((v) => v.id === compareA)?.name}详细结果`} onClick={() => openCase(c, { run: runA!, item: a })} style={{ border: 0, background: "transparent", padding: 0 }}><Status status={a.overallStatus} /></button></td><td onClick={(e) => e.stopPropagation()}><button aria-label={`查看${versions.find((v) => v.id === compareB)?.name}详细结果`} onClick={() => openCase(c, { run: runB!, item: b })} style={{ border: 0, background: "transparent", padding: 0 }}><Status status={b.overallStatus} /></button></td><td><span className="tag">{kind === "fixed" ? "已修复" : kind === "ongoing" ? "持续存在" : kind === "new" ? "新增问题" : a.overallStatus === "pass" && b.overallStatus === "pass" ? "两版通过" : a.overallStatus === "pending_verification" || b.overallStatus === "pending_verification" ? "待核验" : "状态相同"}</span></td><td><ArrowRight size={13} color="#9ba6a6" /></td></tr>; })}</tbody></table></div>}</div></div></>}
        {section === "reviews" && <>
          <div className="grid-main"><div className="card"><div className="card-head"><div><div className="card-title">待复核案例</div><div className="card-sub">复核结论与自动评测结果分开保存</div></div><span className="tag">{reviewQueue.length} 条待处理</span></div><div className="card-body">{reviewQueue.length === 0 ? <div className="empty"><strong>当前没有待复核案例</strong>运行规则评测后，高风险或需人工确认的结果会出现在这里。</div> : <div className="table-wrap"><table className="case-table"><thead><tr><th>案例 / 意图</th><th>评测状态</th><th>问题数</th><th>复核</th><th></th></tr></thead><tbody>{reviewQueue.map(({ c, result }) => <tr key={c.caseId} onClick={() => result && openCase(c, result)}><td><div className="case-id">{c.caseId} · {intentNames[c.intent]}</div><span className="case-question">{c.question}</span></td><td><Status status={result?.item.overallStatus} /></td><td>{result?.item.findings.length ?? 0}</td><td><span className="tag">待人工确认</span></td><td><ArrowRight size={13} /></td></tr>)}</tbody></table></div>}</div></div>
            <div className="card"><div className="card-head"><div><div className="card-title">用户反馈</div><div className="card-sub">显式反馈作为检查线索，不作为事实标签</div></div><button className="btn small" onClick={() => { setFeedbackCase(cases[0]?.caseId ?? ""); setModal("feedback"); }}><Plus size={12} />提交反馈</button></div><div className="card-body">{safeState.feedback.length ? safeState.feedback.map((f) => {
              const pending = !f.status || f.status === "pending_review";
              return <div className="queue-item" key={f.id} style={{ alignItems: "flex-start" }}><i className="queue-bullet" /><div className="queue-copy"><b>{f.kind} · {getCase(f.caseId)?.question ?? f.caseId}</b><span>{f.note} · {new Date(f.createdAt).toLocaleString("zh-CN", { hour12: false })}</span><span className="tag" style={{ marginTop: 6 }}>{pending ? "待处理" : `已处理 · ${f.decision ?? f.status}`}</span>{pending && <div style={{ marginTop: 8 }}>{feedbackResolutionId === f.id ? <><textarea className="field" aria-label="反馈处理说明" placeholder="填写处理依据或后续安排（必填）" value={feedbackResolutionNote} onChange={(e) => setFeedbackResolutionNote(e.target.value)} /><div className="review-actions"><button className="btn small primary" disabled={!feedbackResolutionNote.trim() || !!busy} onClick={() => void resolveFeedback(f.id, "confirmed")}>确认问题</button><button className="btn small" disabled={!feedbackResolutionNote.trim() || !!busy} onClick={() => void resolveFeedback(f.id, "dismissed")}>判为误报</button><button className="btn small" disabled={!feedbackResolutionNote.trim() || !!busy} onClick={() => void resolveFeedback(f.id, "needs_evidence")}>补充证据</button><button className="btn small" onClick={() => { setFeedbackResolutionId(""); setFeedbackResolutionNote(""); }}>取消</button></div></> : <button className="btn small" onClick={() => { setFeedbackResolutionId(f.id); setFeedbackResolutionNote(""); }}>处理反馈</button>}</div>}{!pending && <span style={{ color: "#849192", fontSize: 9 }}>处理说明：{f.resolutionNote || "—"} {f.resolvedAt && `· ${new Date(f.resolvedAt).toLocaleString("zh-CN", { hour12: false })}`}</span>}</div></div>;
            }) : <div className="empty" style={{ padding: "20px 4px" }}>尚无用户反馈</div>}</div></div></div>
          <div className="card" style={{ marginTop: 14 }}><div className="card-head"><div><div className="card-title">已确认问题 · 回归集</div><div className="card-sub">确认问题可加入固定回归案例，后续运行用于检查是否复发。</div></div><button className="btn small" disabled={!safeState.regressionCases?.length || !!busy} onClick={downloadRegression}><Download size={12} />导出回归 JSON</button></div><div className="card-body"><div style={{ marginBottom: 13 }}>{safeState.reviews.filter((r) => r.decision === "confirmed").length ? safeState.reviews.filter((r) => r.decision === "confirmed").map((review) => { const regressionExists = (safeState.regressionCases ?? []).some((item) => item.caseId === review.caseId && item.runId === review.runId); return <div className="queue-item" key={review.id}><i className="queue-bullet" style={{ background: "#429577" }} /><div className="queue-copy"><b>{getCase(review.caseId)?.question ?? review.caseId}</b><span>{review.caseId} · {review.note} · {new Date(review.createdAt).toLocaleString("zh-CN", { hour12: false })}</span></div><button className="btn small" disabled={regressionExists || !!busy} onClick={() => void addRegression(review.runId, review.caseId)}>{regressionExists ? "已加入回归集" : "加入回归集"}</button></div>; }) : <div className="empty" style={{ padding: 12 }}>暂无已确认的问题案例。请先在详情抽屉完成“确认问题”复核。</div>}</div><div className="section-label" style={{ marginTop: 4 }}>回归案例库 · {safeState.regressionCases?.length ?? 0}</div>{safeState.regressionCases?.length ? safeState.regressionCases.map((item) => <div className="queue-item" key={item.id}><i className="queue-bullet" style={{ background: "#429577" }} /><div className="queue-copy"><b>{item.caseSnapshot?.question ?? getCase(item.caseId)?.question ?? item.caseId}</b><span>{item.caseId} · {versions.find((v) => v.id === item.candidateVersionId)?.name ?? item.candidateVersionId} · 加入于 {new Date(item.addedAt).toLocaleString("zh-CN", { hour12: false })}</span></div></div>) : <div style={{ color: "#8c999a", fontSize: 10 }}>尚无回归案例</div>}</div></div>
        </>}
        {section === "tools" && <div className="grid-main"><div className="card"><div className="card-head"><div><div className="card-title">数据工具连接</div><div className="card-sub">可用范围与连接状态透明展示</div></div><button className="btn small" onClick={() => void refresh(true)}><RefreshCw size={12} />刷新状态</button></div><div className="card-body"><div className="tool-grid">{safeState.tools.map((t) => <div className="tool-card" key={t.id}><div className="tool-top"><b>{t.name}</b><span className={`tool-status ${t.status === "not_configured" || t.status === "simulated_timeout" ? "off" : ""}`}><i className={`dot ${t.status === "not_configured" ? "" : ""}`} style={{ background: t.status === "snapshot" ? "#4ab28f" : "#d6a147" }} />{t.status === "snapshot" ? "合成快照可用" : t.status === "simulated_timeout" ? "模拟超时" : "未配置"}</span></div><p>{t.description}</p><button className="btn small" onClick={() => void probe(t.id)} disabled={!!busy}>{busy === "probe" ? <LoaderCircle className="spin" size={12} /> : <Zap size={12} />}演示异常场景</button></div>)}{ifindInfo && <div className="tool-card" style={{ gridColumn: "1 / -1", borderColor: "#cde5df", background: "#fbfefd" }}><div className="tool-top"><b>iFinD 行情查询</b><span className={`tool-status ${ifindInfo.configured ? "" : "off"}`}><i className="dot" style={{ background: ifindInfo.configured ? "#4ab28f" : "#d6a147" }} />{ifindInfo.configured ? "连接可用" : "服务端未配置"}</span></div><p>查询 300033.SZ 于 2026-11-06 的收盘价。原始数据仅供人工核验，查询结果不会自动写入回答评测或判定回答正确。</p><label className="field-label" style={{ marginTop: 8 }}>待核验的回答数值（元，可选）</label><input className="field" inputMode="decimal" placeholder="留空时仅查询 iFinD" value={ifindClaim} onChange={(e) => setIfindClaim(e.target.value)} /><button className="btn small primary" style={{ marginTop: 8 }} onClick={() => void ifindQuery()} disabled={!!busy || (!!ifindClaim.trim() && !Number.isFinite(Number(ifindClaim)))}>{busy === "ifind" ? <LoaderCircle size={12} className="spin" /> : <Search size={12} />}{ifindClaim.trim() ? "查询并核验" : "查询 iFinD"}</button>{ifindResult && <div style={{ marginTop: 13, padding: 11, background: "#f4f8f7", borderRadius: 7, border: "1px solid #e3ece9" }}><div style={{ display: "flex", justifyContent: "space-between", fontSize: 9, color: "#637577", marginBottom: 7 }}><b>{ifindResult.status === "retrieved" ? "查询已返回" : ifindResult.status === "not_configured" ? "未配置" : "查询异常"}</b><span>{ifindResult.source} {ifindResult.retrievedAt ? `· ${new Date(ifindResult.retrievedAt).toLocaleString("zh-CN", { hour12: false })}` : ""}</span></div>{ifindResult.verification && <div style={{ marginBottom: 8, padding: "8px 9px", borderRadius: 6, background: ifindResult.verification.status === "MATCH" ? "#eaf7f0" : ifindResult.verification.status === "MISMATCH" ? "#fff0ee" : "#fff7e8", color: ifindResult.verification.status === "MATCH" ? "#347e61" : ifindResult.verification.status === "MISMATCH" ? "#a74e45" : "#966d2c", fontSize: 9 }}><b>{ifindResult.verification.status === "MATCH" ? "数值匹配" : ifindResult.verification.status === "MISMATCH" ? "数值不匹配" : "待核验"}</b>　回答值 {ifindResult.verification.claimedValue} {ifindResult.verification.unit} · 来源值 {ifindResult.verification.referenceValue ?? "—"} {ifindResult.verification.unit}<div style={{ marginTop: 4 }}>来源：{ifindResult.verification.symbol} · {ifindResult.verification.date} · {ifindResult.verification.adjustment} · 证据 {ifindResult.verification.evidenceId}</div><div style={{ marginTop: 3 }}>{ifindResult.verification.reason}</div></div>}{ifindResult.notice && <p style={{ margin: "0 0 7px", color: "#738384", fontSize: 9 }}>{ifindResult.notice}</p>}<pre style={{ whiteSpace: "pre-wrap", overflowWrap: "anywhere", margin: 0, fontSize: 9, color: "#40575a", maxHeight: 180, overflow: "auto" }}>{ifindResult.content?.map((c) => c.text).join("\n") || JSON.stringify(ifindResult.query ?? ifindResult, null, 2)}</pre><button className="btn small" style={{ marginTop: 8 }} onClick={downloadIfind}><Download size={11} />下载查询 JSON</button></div>}</div>}</div><div className="notice" style={{ marginTop: 12, marginBottom: 0 }}><Sparkles size={14} /><span>AI 语义评测：{judgeInfo?.configured ? `已配置 · ${judgeInfo.model || "模型可用"}` : "未配置"}。未配置时不会生成 AI 结论。</span></div><div className="notice" style={{ marginTop: 12, marginBottom: 0 }}><AlertCircle size={14} /><span>工具探测的模拟异常仅验证错误路径，不代表真实数据源故障。合成证据快照和 iFinD 查询结果彼此独立。</span></div></div></div><div className="card"><div className="card-head"><div><div className="card-title">生效中的 Skills</div><div className="card-sub">规则定义、版本及适用范围</div></div><Sparkles size={15} color="#6b9f94" /></div><div className="card-body">{(safeState.skills ?? safeState.evaluationVersions?.flatMap((ev) => ev.rules.map((rule, i) => ({ id: `${ev.id}-${i}`, name: rule, version: ev.skillVersion, description: ev.name }))) ?? []).map((s) => <div className="skill-row" key={s.id}><div className="skill-icon"><Sparkles size={13} /></div><div><b>{s.name}</b><small>{s.description || "评测规则与检查标准"}</small></div><span className="skill-version">{s.version || s.status || "已启用"}</span></div>)}{!safeState.skills?.length && !safeState.evaluationVersions?.length && <div className="empty">暂无 Skills 数据</div>}<div className="notice" style={{ marginTop: 12, marginBottom: 0 }}><ShieldCheck size={14} /><span>规则负责可重复的字段和数字检查；模型语义评测目前未配置，不会伪装成已运行。</span></div><button className="btn small danger" style={{ marginTop: 14 }} disabled={!!busy} onClick={() => void resetDemo()}><RefreshCw size={12} />重置本会话演示数据</button></div></div></div>}
      </div>
    </main>
    <button className="feedback-fab" onClick={() => { setFeedbackCase(cases[0]?.caseId ?? ""); setModal("feedback"); }}><MessageSquareText />提交反馈</button>
    {toast && <div className={`toast ${toast.error ? "error" : ""}`}><span>{toast.error ? "操作未完成 · " : "已完成 · "}</span>{toast.text}</div>}
    {modal && <div className="modal-backdrop" onMouseDown={(e) => { if (e.target === e.currentTarget) setModal(null); }}><div className="modal"><div className="modal-head"><h2>{modal === "import" ? "导入问答集" : "提交回答反馈"}</h2><button aria-label="关闭对话框" className="top-icon" onClick={() => setModal(null)}><X size={14} /></button></div>{modal === "import" ? <><div className="modal-body"><p style={{ margin: "0 0 12px", color: "#788688", fontSize: 10, lineHeight: 1.7 }}>导入 JSON 问答数据。支持包含 <code>cases</code> 数组的数据集对象；示例案例字段包括 question、intent、answers、kyc 和 evidence。</p><button className="btn small" onClick={downloadExample}><FileJson2 size={12} />下载格式示例</button><textarea className="field" style={{ height: 220, resize: "vertical", marginTop: 10, fontFamily: "ui-monospace,monospace", fontSize: 10 }} placeholder="粘贴 JSON，或选择文件…" value={importText} onChange={(e) => setImportText(e.target.value)} /><label className="btn small" style={{ marginTop: 9, display: "inline-flex" }}><Upload size={12} />选择 JSON 文件<input type="file" accept="application/json,.json" hidden onChange={(e) => { const f = e.target.files?.[0]; if (f) void f.text().then(setImportText); }} /></label></div><div className="modal-foot"><button className="btn" onClick={() => setModal(null)}>取消</button><button className="btn primary" onClick={() => void importData()} disabled={!importText.trim() || !!busy}>{busy === "import" ? <LoaderCircle className="spin" /> : <Upload />}导入问答集</button></div></> : <><div className="modal-body"><label className="field-label">关联案例</label><select className="field" value={feedbackCase} onChange={(e) => setFeedbackCase(e.target.value)}>{cases.map((c) => <option value={c.caseId} key={c.caseId}>{c.caseId} · {c.question}</option>)}</select><label className="field-label">反馈类型</label><select className="field" value={feedbackKind} onChange={(e) => setFeedbackKind(e.target.value)}>{["事实可能错误", "没有回答问题", "不适合我的情况", "表达不清楚"].map((x) => <option key={x}>{x}</option>)}</select><label className="field-label">具体说明 <span style={{ color: "#a1aaaa", fontWeight: 400 }}>（必填）</span></label><textarea className="field" style={{ height: 104, resize: "vertical" }} placeholder="说明你发现的问题或希望补充的内容…" value={feedbackNote} onChange={(e) => setFeedbackNote(e.target.value)} /></div><div className="modal-foot"><button className="btn" onClick={() => setModal(null)}>取消</button><button className="btn primary" onClick={() => void submitFeedback()} disabled={!feedbackNote.trim() || !!busy}>{busy === "feedback" ? <LoaderCircle className="spin" /> : <MessageSquareText />}提交反馈</button></div></>}</div></div>}
    {selected && <><div className="drawer-shade" onClick={() => setSelected(null)} /><aside className="drawer"><div className="drawer-head"><div><h2>回答质检详情</h2><small>{selected.c.caseId} · {intentNames[selected.c.intent]} · {statusNames[selected.item.overallStatus]}</small></div><button aria-label="关闭详情抽屉" className="top-icon" onClick={() => setSelected(null)}><PanelRightClose size={15} /></button></div><div className="drawer-content"><div className="detail-card"><h3>用户问题</h3><p>{selected.c.question}</p></div><div className="detail-card"><h3>匿名 KYC 画像</h3><div className="kyc-grid"><Kyc label="投资经验" value={selected.c.kyc.experience === "beginner" ? "初级" : selected.c.kyc.experience === "experienced" ? "有经验" : "未提供"} /><Kyc label="风险承受" value={riskLabel(selected.c.kyc.riskTolerance)} /><Kyc label="投资期限" value={selected.c.kyc.horizonMonths ? `${selected.c.kyc.horizonMonths} 个月` : "未提供"} /><Kyc label="流动性需求" value={riskLabel(selected.c.kyc.liquidityNeed)} /><Kyc label="资金用途" value={selected.c.kyc.purpose || "未提供"} /><Kyc label="案例属性" value="合成测试数据" /></div></div>{selected.c.eventContext?.length ? <EventContextCard events={selected.c.eventContext} askedAt={selected.c.askedAt} answerGeneratedAt={selectedAnswerGeneratedAt} /> : null}<div className="detail-card"><h3>候选回答 <span className="tag" style={{ marginLeft: 5 }}>{selected.item.answerProvenance === "preset" ? "预置回答" : "生成回答"}</span></h3><p>{selected.item.answerText}</p><div style={{ borderTop: "1px solid #edf0ef", marginTop: 11, paddingTop: 9, fontSize: 9, color: "#8b999a" }}>候选版本：{versions.find((v) => v.id === selected.run.candidateVersionId)?.name ?? selected.run.candidateVersionId}　·　运行记录：{new Date(selected.run.createdAt).toLocaleString("zh-CN", { hour12: false })}</div></div><div className="detail-card"><h3>问题片段与规则判断 <span className="tag">{selected.item.findings.length} 项</span></h3>{selected.item.findings.length ? selected.item.findings.map((f) => <div className="finding" key={f.id} style={{ borderColor: f.severity === "critical" || f.severity === "high" ? "#d87668" : "#d6a44c" }}><div style={{ display: "flex", justifyContent: "space-between", gap: 10 }}><b>{f.dimension} · {f.ruleId}</b><span className="tag">{severityNames[f.severity]} · {f.status === "fail" ? "命中" : "待核验"}</span></div>{f.quote && <p><span className="quote">{f.quote}</span></p>}<p><b>原因候选 · 待人工确认：</b>{f.reason}</p>{f.evidenceIds.length > 0 && <p style={{ color: "#7b898a" }}>关联证据：{f.evidenceIds.join("、")}</p>}</div>) : <p>当前没有发现问题片段。</p>}</div><div className="detail-card"><h3>AI 辅助复核 <span className="tag" style={{ marginLeft: 5 }}>{judgeInfo?.configured ? judgeInfo.model || "模型已配置" : "模型未配置"}</span></h3><p>AI 输出作为独立建议，需由人工核验，不并入规则评测指标。</p>{judgeResult?.result && <div style={{ marginTop: 10, borderTop: "1px solid #edf0ef", paddingTop: 10 }}><div style={{ display: "flex", justifyContent: "space-between", fontSize: 10 }}><b>{judgeResult.result.summary}</b><span className="tag">{statusNames[judgeResult.result.overallStatus] || judgeResult.result.overallStatus}</span></div>{judgeResult.result.findings.map((f, i) => <div className="finding" key={`${f.dimension}-${i}`}><b>{f.dimension} · {severityNames[f.severity] || f.severity}</b>{f.quote && <p><span className="quote">{f.quote}</span></p>}<p><b>建议原因 · 待人工确认：</b>{f.reason}</p>{f.evidenceIds.length > 0 && <p>关联证据：{f.evidenceIds.join("、")}</p>}</div>)}<p style={{ color: "#8a9899", fontSize: 9 }}>模型：{judgeResult.model} · 规则版本：{judgeResult.skillVersion} · {judgeResult.createdAt ? new Date(judgeResult.createdAt).toLocaleString("zh-CN", { hour12: false }) : ""}</p></div>}{judgeResult?.notice && <p style={{ marginTop: 8, fontSize: 9 }}>{judgeResult.notice}</p>}<button className="btn small" style={{ marginTop: 9 }} disabled={!!busy || !judgeInfo?.configured} onClick={() => void judgeCase(selected.c, selected.run.candidateVersionId)}>{busy === "judge" ? <LoaderCircle size={12} className="spin" /> : <Sparkles size={12} />}运行 AI 辅助复核</button></div><div className="detail-card"><h3>合成事实证据快照 <span className="tag">{selected.c.evidence.length} 条</span></h3>{selected.c.evidence.length ? <div className="table-wrap"><table className="evidence"><thead><tr><th>核验字段</th><th>快照值</th><th>期间</th><th>来源</th></tr></thead><tbody>{selected.c.evidence.map((e) => <tr key={e.id}><td>{e.claim}</td><td>{e.value} {e.unit}</td><td>{e.period}</td><td>{e.source} · {e.publishedAt.slice(0, 10)}</td></tr>)}</tbody></table></div> : <p>此案例没有配置合成证据快照，相关事实不能据此确认。</p>}<p style={{ marginTop: 9, color: "#9b793e", fontSize: 9 }}>证据为合成演示数据，不代表实时行情；查询时间与发布时点以快照记录为准。</p></div><div className="review-form"><h3>人工复核 <span className="tag">自动评测：{statusNames[selected.item.overallStatus]}</span></h3><label className="field-label" style={{ marginTop: 4 }}>复核理由（必填）</label><textarea className="field" style={{ height: 72, resize: "vertical" }} placeholder="说明确认依据、误报原因或需要补充的证据…" value={reviewNote} onChange={(e) => setReviewNote(e.target.value)} /><div className="review-actions"><button className="btn small primary" onClick={() => void submitReview("confirmed")} disabled={!reviewNote.trim() || !!busy}><Check size={12} />确认问题</button><button className="btn small" onClick={() => void submitReview("false_positive")} disabled={!reviewNote.trim() || !!busy}>判为误报</button><button className="btn small" onClick={() => void submitReview("needs_evidence")} disabled={!reviewNote.trim() || !!busy}>要求补充证据</button></div></div><div style={{ display: "flex", justifyContent: "space-between", marginTop: 12 }}><button className="btn small" onClick={() => { setSelected(null); setFeedbackCase(selected.c.caseId); setModal("feedback"); }}><MessageSquareText size={12} />提交反馈</button><button className="btn small" onClick={() => void generate(selected.c, selected.run.candidateVersionId)} disabled={!!busy}><Sparkles size={12} />生成修订回答</button></div></div></aside></>}
  </div>;
}

function Stat({ Icon, title, value, note, accent = false }: { Icon: typeof Gauge; title: string; value: string | number; note: string; accent?: boolean }) { return <div className="stat"><div className="stat-top"><span>{title}</span><span className="stat-icon" style={accent ? { background: "#fff5e6", color: "#ad7b35" } : {}}><Icon /></span></div><div className="stat-value">{value}</div><div className="stat-foot">{note}</div></div>; }
function Status({ status }: { status?: string }) { return <span className={`status ${status ?? "idle"}`}>{statusNames[status ?? "idle"] ?? "未评测"}</span>; }
function CaseTable({ cases, items, onOpen, selectable = false, checkedIds = [], onToggle, answerVersionId }: { cases: QualityCase[]; items: Map<string, { run: EvalRun; item: RunItem }>; onOpen: (c: QualityCase) => void; selectable?: boolean; checkedIds?: string[]; onToggle?: (caseId: string) => void; answerVersionId?: string }) { return <div className="table-wrap"><table className="case-table"><thead><tr>{selectable && <th style={{ width: 34 }}>选</th>}<th>测试案例</th><th>意图</th><th>质量状态</th><th>问题数</th><th>证据覆盖率</th><th></th></tr></thead><tbody>{cases.map((c) => { const result = items.get(c.caseId); const hasAnswer = !answerVersionId || !!c.answers[answerVersionId]?.text?.trim(); return <tr key={c.caseId} onClick={() => onOpen(c)}>{selectable && <td onClick={(e) => e.stopPropagation()}><input aria-label={`选择 ${c.caseId}`} title={hasAnswer ? `选择 ${c.caseId}` : "此版本尚无此案例的回答"} type="checkbox" disabled={!hasAnswer} checked={checkedIds.includes(c.caseId)} onChange={() => onToggle?.(c.caseId)} /></td>}<td><div className="case-id">{c.caseId} · 合成案例</div><span className="case-question">{c.question}</span></td><td><span className="tag">{intentNames[c.intent]}</span></td><td><Status status={result?.item.overallStatus} /></td><td>{result?.item.findings.length ?? "—"}</td><td>{result && result.item.verifiedDenominator ? `${result.item.verifiedNumerator}/${result.item.verifiedDenominator}` : "不适用"}</td><td><ArrowRight size={13} color="#9ba6a6" /></td></tr>; })}</tbody></table>{cases.length === 0 && <div className="empty"><strong>没有匹配的案例</strong>调整筛选条件，或导入新的问答数据。</div>}</div>; }
function VersionCard({ version, letter }: { version: CandidateVersion; letter: string }) { return <div className="version-card"><div className="version-head"><div className="version-mark">{letter}</div><div><b>{version.name}</b><small>{version.model}</small></div><span className="tag" style={{ marginLeft: "auto" }}>候选版本</span></div><p>{version.description}</p><div className="metadata"><span>Prompt</span><span>{version.promptVersion}</span><span>数据快照</span><span>{version.dataSnapshot}</span></div></div>; }
function DiffStat({ label, value, detail, color }: { label: string; value: number | string; detail: string; color: string }) { return <div className="diff-stat"><span>{label}</span><b style={{ color }}>{value}</b><small>{detail}</small></div>; }
function Ratio({ label, numerator, denominator }: { label: string; numerator: number; denominator: number }) { return <div style={{ border: "1px solid #e9eeee", borderRadius: 8, padding: "10px 11px", display: "flex", justifyContent: "space-between", alignItems: "center" }}><span style={{ color: "#768587", fontSize: 10 }}>{label}</span><b style={{ color: "#354b4d", fontSize: 11 }}>{denominator ? `${Math.round(100 * numerator / denominator)}% · ${numerator}/${denominator}` : "— · 0/0"}</b></div>; }
function Kyc({ label, value }: { label: string; value: string }) { return <div className="kyc"><small>{label}</small><b>{value}</b></div>; }
function riskLabel(value: "low" | "medium" | "high" | null) { return value === "low" ? "低" : value === "medium" ? "中" : value === "high" ? "高" : "未提供"; }
function EventContextCard({ events, askedAt, answerGeneratedAt }: { events: EventContext[]; askedAt: string; answerGeneratedAt?: string }) { return <div className="detail-card"><h3>事件上下文 <span className="tag">合成数据</span></h3><div style={{ display: "grid", gap: 10 }}>{events.map((event) => <div key={event.id} style={{ borderLeft: "2px solid #71b9aa", paddingLeft: 10 }}><b style={{ fontSize: 10, color: "#37494b" }}>{event.title}</b><div style={{ marginTop: 5, color: "#7d8b8c", fontSize: 9 }}>事件发生 {new Date(event.occurredAt).toLocaleString("zh-CN", { hour12: false })} · 信息公开 {new Date(event.publishedAt).toLocaleString("zh-CN", { hour12: false })}</div><div style={{ marginTop: 5, color: "#5d7072", fontSize: 10, lineHeight: 1.65 }}>{event.summary}</div><div style={{ marginTop: 5, color: "#869394", fontSize: 9 }}>来源：{event.source} · 问答时点：{new Date(askedAt).toLocaleString("zh-CN", { hour12: false })} · 回答生成：{answerGeneratedAt ? new Date(answerGeneratedAt).toLocaleString("zh-CN", { hour12: false }) : "历史运行未单独保存生成时点"}</div></div>)}</div></div>; }
